{
  "name": "Super League Table Manager",
  "description": "A professional-grade football league management system with interactive standings, match scheduling, and AI-powered commentary for a 6-team competition."
}

export interface Team {
  id: string;
  name: string;
  playerName: string;
  isHuman: boolean;
  color: string;
}

export interface Match {
  id: string;
  homeId: string;
  awayId: string;
  homeScore: number | null;
  awayScore: number | null;
  round: number;
}

export interface StandingRow {
  teamId: string;
  teamName: string;
  isHuman: boolean;
  played: number;
  won: number;
  drawn: number;
  lost: number;
  gf: number;
  ga: number;
  gd: number;
  points: number;
  lastFive: ('W' | 'D' | 'L' | '-')[];
}

export type AppState = 'setup' | 'league';

import { GoogleGenAI } from "@google/genai";
import { StandingRow, Match, Team } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getLeagueAnalysis(standings: StandingRow[], teams: Team[]) {
  const standingsContext = standings.map((s, idx) => 
    `${idx + 1}. ${s.teamName} (${s.isHuman ? 'Player: ' + teams.find(t => t.id === s.teamId)?.playerName : 'AI'}): ${s.points}pts, ${s.won}W, GD: ${s.gd}`
  ).join('\n');

  const prompt = `
    Você é um comentarista esportivo sarcástico e divertido.
    Analise a seguinte tabela classificatória de uma liga de 6 times (Brasileirão Style):

    ${standingsContext}

    Dê um resumo curto (máximo 3 parágrafos) sobre quem está dominando, quem está passando vergonha e faça uma previsão engraçada para o final da temporada. 
    Lembre-se: mencione nomes de jogadores humanos se houver algum. Use termos do futebol brasileiro.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return "O narrador perdeu a voz! (Erro ao gerar comentário)";
  }
}

import React, { useState } from 'react';
import { Match, Team } from '../types';

interface Props {
  matches: Match[];
  teams: Team[];
  onUpdateScore: (matchId: string, homeScore: number, awayScore: number) => void;
}

const MatchList: React.FC<Props> = ({ matches, teams, onUpdateScore }) => {
  const [selectedRound, setSelectedRound] = useState(1);
  const totalRounds = Math.max(...matches.map(m => m.round));

  const filteredMatches = matches.filter(m => m.round === selectedRound);

  const getTeam = (id: string) => teams.find(t => t.id === id);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between bg-slate-800/50 p-3 rounded-lg border border-slate-700 overflow-x-auto">
        <div className="flex gap-2">
          {Array.from({ length: totalRounds }, (_, i) => i + 1).map(round => (
            <button
              key={round}
              onClick={() => setSelectedRound(round)}
              className={`px-4 py-2 rounded-md font-bold text-sm transition-all min-w-[60px] ${
                selectedRound === round 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' 
                  : 'bg-slate-700 text-slate-400 hover:bg-slate-600'
              }`}
            >
              R{round}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {filteredMatches.map(match => {
          const home = getTeam(match.homeId);
          const away = getTeam(match.awayId);

          return (
            <div key={match.id} className="bg-slate-800 border border-slate-700 p-4 rounded-xl flex items-center justify-between hover:border-blue-500/50 transition-all shadow-lg group">
              <div className="flex-1 text-right pr-4">
                <div className="font-bold text-white group-hover:text-blue-400 transition-colors">{home?.name}</div>
                <div className="text-[10px] text-slate-500 uppercase">{home?.isHuman ? home.playerName : 'AI'}</div>
              </div>

              <div className="flex items-center gap-2">
                <input
                  type="number"
                  min="0"
                  value={match.homeScore ?? ''}
                  onChange={(e) => onUpdateScore(match.id, parseInt(e.target.value) || 0, match.awayScore ?? 0)}
                  placeholder="0"
                  className="w-12 h-12 bg-slate-900 border border-slate-700 rounded text-center font-black text-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-white"
                />
                <span className="text-slate-600 font-bold">x</span>
                <input
                  type="number"
                  min="0"
                  value={match.awayScore ?? ''}
                  onChange={(e) => onUpdateScore(match.id, match.homeScore ?? 0, parseInt(e.target.value) || 0)}
                  placeholder="0"
                  className="w-12 h-12 bg-slate-900 border border-slate-700 rounded text-center font-black text-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-white"
                />
              </div>

              <div className="flex-1 text-left pl-4">
                <div className="font-bold text-white group-hover:text-blue-400 transition-colors">{away?.name}</div>
                <div className="text-[10px] text-slate-500 uppercase">{away?.isHuman ? away.playerName : 'AI'}</div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default MatchList;

import React, { useState } from 'react';
import { Team } from '../types';
import { DEFAULT_BOT_NAMES, TEAM_COLORS, TOTAL_TEAMS } from '../constants';

interface Props {
  onStart: (teams: Team[]) => void;
}

const SetupForm: React.FC<Props> = ({ onStart }) => {
  const [numHumans, setNumHumans] = useState(1);
  const [humanInputs, setHumanInputs] = useState(
    Array.from({ length: TOTAL_TEAMS }, (_, i) => ({
      playerName: `Jogador ${i + 1}`,
      teamName: `Time ${i + 1}`,
    }))
  );

  const handleStart = () => {
    const finalTeams: Team[] = [];

    // Shuffle bot names for variety
    const availableBots = [...DEFAULT_BOT_NAMES].sort(() => Math.random() - 0.5);

    for (let i = 0; i < TOTAL_TEAMS; i++) {
      if (i < numHumans) {
        finalTeams.push({
          id: `team-${i}`,
          name: humanInputs[i].teamName,
          playerName: humanInputs[i].playerName,
          isHuman: true,
          color: TEAM_COLORS[i % TEAM_COLORS.length]
        });
      } else {
        finalTeams.push({
          id: `team-${i}`,
          name: availableBots[i - numHumans] || `AI Team ${i}`,
          playerName: 'Computador',
          isHuman: false,
          color: TEAM_COLORS[i % TEAM_COLORS.length]
        });
      }
    }
    onStart(finalTeams);
  };

  return (
    <div className="max-w-2xl mx-auto bg-slate-800 p-8 rounded-2xl shadow-2xl border border-slate-700 animate-in fade-in zoom-in duration-500">
      <h2 className="text-3xl font-black mb-6 text-white text-center">Configurar Campeonato</h2>

      <div className="mb-8">
        <label className="block text-slate-400 text-sm font-bold mb-2">Quantas pessoas vão jogar?</label>
        <div className="grid grid-cols-6 gap-2">
          {[1, 2, 3, 4, 5, 6].map(num => (
            <button
              key={num}
              onClick={() => setNumHumans(num)}
              className={`py-3 rounded-lg font-bold border-2 transition-all ${
                numHumans === num 
                  ? 'bg-blue-600 border-blue-400 text-white' 
                  : 'bg-slate-900 border-slate-700 text-slate-500 hover:bg-slate-700'
              }`}
            >
              {num}
            </button>
          ))}
        </div>
      </div>

      <div className="space-y-4 mb-8">
        {Array.from({ length: numHumans }).map((_, i) => (
          <div key={i} className="p-4 bg-slate-900 rounded-xl border border-slate-700 flex gap-4">
            <div className="flex-1">
              <label className="block text-slate-500 text-[10px] font-bold uppercase mb-1">Nome do Jogador</label>
              <input
                value={humanInputs[i].playerName}
                onChange={(e) => {
                  const newInputs = [...humanInputs];
                  newInputs[i].playerName = e.target.value;
                  setHumanInputs(newInputs);
                }}
                className="w-full bg-slate-800 border border-slate-700 rounded px-3 py-2 text-white focus:outline-none focus:ring-1 focus:ring-blue-500"
              />
            </div>
            <div className="flex-1">
              <label className="block text-slate-500 text-[10px] font-bold uppercase mb-1">Nome do Time</label>
              <input
                value={humanInputs[i].teamName}
                onChange={(e) => {
                  const newInputs = [...humanInputs];
                  newInputs[i].teamName = e.target.value;
                  setHumanInputs(newInputs);
                }}
                className="w-full bg-slate-800 border border-slate-700 rounded px-3 py-2 text-white focus:outline-none focus:ring-1 focus:ring-blue-500"
              />
            </div>
          </div>
        ))}
      </div>

      <button
        onClick={handleStart}
        className="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-black py-4 rounded-xl transition-all shadow-xl shadow-emerald-500/20 uppercase tracking-widest active:scale-95"
      >
        Iniciar Campeonato
      </button>
    </div>
  );
};

export default SetupForm;

import React, { useState, useMemo, useCallback } from 'react';
import { Team, Match, StandingRow, AppState } from './types';
import SetupForm from './components/SetupForm';
import LeagueTable from './components/LeagueTable';
import MatchList from './components/MatchList';
import { getLeagueAnalysis } from './services/geminiService';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('setup');
  const [teams, setTeams] = useState<Team[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [analysis, setAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Generate a round-robin schedule for 6 teams
  const generateSchedule = (teamList: Team[]) => {
    const rounds: Match[] = [];
    const n = teamList.length;
    const teamIds = teamList.map(t => t.id);

    // Basic Round-Robin (First Half)
    for (let round = 0; round < n - 1; round++) {
      for (let i = 0; i < n / 2; i++) {
        const home = teamIds[i];
        const away = teamIds[n - 1 - i];
        rounds.push({
          id: `match-${round}-${i}`,
          homeId: home,
          awayId: away,
          homeScore: null,
          awayScore: null,
          round: round + 1
        });
      }
      // Rotate
      const last = teamIds.pop()!;
      teamIds.splice(1, 0, last);
    }

    // Return Match (Second Half)
    const secondHalf = rounds.map(m => ({
      ...m,
      id: `match-ret-${m.id}`,
      homeId: m.awayId,
      awayId: m.homeId,
      round: m.round + (n - 1)
    }));

    return [...rounds, ...secondHalf];
  };

  const handleStart = (selectedTeams: Team[]) => {
    setTeams(selectedTeams);
    setMatches(generateSchedule(selectedTeams));
    setAppState('league');
  };

  const updateScore = (matchId: string, homeScore: number, awayScore: number) => {
    setMatches(prev => prev.map(m => m.id === matchId ? { ...m, homeScore, awayScore } : m));
  };

  const standings = useMemo(() => {
    const stats: Record<string, StandingRow> = {};

    teams.forEach(t => {
      stats[t.id] = {
        teamId: t.id,
        teamName: t.name,
        isHuman: t.isHuman,
        played: 0,
        won: 0,
        drawn: 0,
        lost: 0,
        gf: 0,
        ga: 0,
        gd: 0,
        points: 0,
        lastFive: []
      };
    });

    // Calculate match results
    const sortedMatches = [...matches].sort((a, b) => a.round - b.round);
    const resultsByTeam: Record<string, ('W' | 'D' | 'L')[]> = {};
    teams.forEach(t => resultsByTeam[t.id] = []);

    sortedMatches.forEach(m => {
      if (m.homeScore !== null && m.awayScore !== null) {
        const home = stats[m.homeId];
        const away = stats[m.awayId];

        home.played++;
        away.played++;
        home.gf += m.homeScore;
        home.ga += m.awayScore;
        away.gf += m.awayScore;
        away.ga += m.homeScore;

        if (m.homeScore > m.awayScore) {
          home.won++;
          home.points += 3;
          away.lost++;
          resultsByTeam[m.homeId].push('W');
          resultsByTeam[m.awayId].push('L');
        } else if (m.homeScore < m.awayScore) {
          away.won++;
          away.points += 3;
          home.lost++;
          resultsByTeam[m.homeId].push('L');
          resultsByTeam[m.awayId].push('W');
        } else {
          home.drawn++;
          away.drawn++;
          home.points += 1;
          away.points += 1;
          resultsByTeam[m.homeId].push('D');
          resultsByTeam[m.awayId].push('D');
        }
        home.gd = home.gf - home.ga;
        away.gd = away.gf - away.ga;
      }
    });

    // Final mapping and sorting
    return Object.values(stats)
      .map(s => ({
        ...s,
        lastFive: resultsByTeam[s.teamId].slice(-5).reverse()
      }))
      .sort((a, b) => {
        if (b.points !== a.points) return b.points - a.points;
        if (b.won !== a.won) return b.won - a.won;
        if (b.gd !== a.gd) return b.gd - a.gd;
        return b.gf - a.gf;
      });
  }, [matches, teams]);

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const result = await getLeagueAnalysis(standings, teams);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  return (
    <div className="min-h-screen pb-20 selection:bg-blue-500/30">
      {/* Header */}
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-30 shadow-xl px-4 py-4 mb-8">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-emerald-500 rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/20">
              <span className="text-white font-black text-xl">L</span>
            </div>
            <div>
              <h1 className="text-xl font-black text-white tracking-tighter">SUPER LEAGUE</h1>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Interactive Table System</p>
            </div>
          </div>
          {appState === 'league' && (
            <button 
              onClick={() => setAppState('setup')}
              className="text-slate-400 hover:text-white transition-colors text-sm font-bold flex items-center gap-2"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M4 2a1 1 0 011 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 010 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v5a1 1 0 11-2 0v-2.101a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd" />
              </svg>
              Reiniciar
            </button>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4">
        {appState === 'setup' ? (
          <SetupForm onStart={handleStart} />
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-2 space-y-8">
              <section className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="text-2xl font-black text-white flex items-center gap-3">
                    <span className="w-2 h-8 bg-blue-500 rounded-full"></span>
                    Classificação
                  </h2>
                </div>
                <LeagueTable standings={standings} />
              </section>

              <section className="animate-in fade-in slide-in-from-bottom-4 duration-700">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="text-2xl font-black text-white flex items-center gap-3">
                    <span className="w-2 h-8 bg-emerald-500 rounded-full"></span>
                    Partidas
                  </h2>
                </div>
                <MatchList matches={matches} teams={teams} onUpdateScore={updateScore} />
              </section>
            </div>

            <div className="space-y-6">
              <section className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700 shadow-xl animate-in fade-in slide-in-from-right-4 duration-1000">
                <div className="flex items-center gap-3 mb-4">
                  <div className="w-8 h-8 bg-purple-600 rounded flex items-center justify-center text-white">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M18 10c0 3.866-3.582 7-8 7a8.841 8.841 0 01-4.083-.98L2 17l1.338-3.123C2.493 12.767 2 11.434 2 10c0-3.866 3.582-7 8-7s8 3.134 8 7zM7 9H5v2h2V9zm8 0h-2v2h2V9zM9 9h2v2H9V9z" clipRule="evenodd" />
                    </svg>
                  </div>
                  <h3 className="text-lg font-black text-white">Análise do Narrador AI</h3>
                </div>

                {analysis ? (
                  <div className="prose prose-invert text-slate-300 text-sm leading-relaxed whitespace-pre-wrap italic bg-slate-900/50 p-4 rounded-xl border border-slate-700">
                    {analysis}
                  </div>
                ) : (
                  <div className="text-slate-500 text-sm italic mb-4">
                    Nenhuma análise gerada ainda. Peça para o narrador comentar a situação atual!
                  </div>
                )}

                <button 
                  onClick={handleAnalyze}
                  disabled={isAnalyzing}
                  className={`mt-4 w-full flex items-center justify-center gap-2 py-3 px-4 rounded-xl font-bold transition-all ${
                    isAnalyzing 
                      ? 'bg-slate-700 text-slate-500 cursor-not-allowed' 
                      : 'bg-gradient-to-r from-purple-600 to-indigo-600 text-white hover:shadow-lg hover:shadow-purple-500/20 active:scale-95'
                  }`}
                >
                  {isAnalyzing ? (
                    <>
                      <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                      Comentando...
                    </>
                  ) : (
                    <>Gerar Comentário</>
                  )}
                </button>
              </section>

              <section className="bg-gradient-to-br from-slate-800 to-slate-900 rounded-2xl p-6 border border-slate-700 shadow-xl">
                 <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4">Resumo da Liga</h3>
                 <div className="space-y-3">
                    <div className="flex justify-between items-center py-2 border-b border-slate-700/50">
                      <span className="text-slate-400 text-xs">Total de Jogos</span>
                      <span className="text-white font-bold">{matches.length}</span>
                    </div>
                    <div className="flex justify-between items-center py-2 border-b border-slate-700/50">
                      <span className="text-slate-400 text-xs">Gols Marcados</span>
                      <span className="text-white font-bold">{matches.reduce((acc, m) => acc + (m.homeScore || 0) + (m.awayScore || 0), 0)}</span>
                    </div>
                    <div className="flex justify-between items-center py-2 border-b border-slate-700/50">
                      <span className="text-slate-400 text-xs">Aproveitamento Líder</span>
                      <span className="text-emerald-400 font-bold">
                        {standings[0].played > 0 ? `${((standings[0].points / (standings[0].played * 3)) * 100).toFixed(1)}%` : '0%'}
                      </span>
                    </div>
                 </div>
              </section>
            </div>
          </div>
        )}
      </main>

      <footer className="mt-20 border-t border-slate-800 py-8 text-center text-slate-600 text-xs font-medium uppercase tracking-[0.2em]">
        © {new Date().getFullYear()} Super League Table Manager • Powered by Gemini AI
      </footer>
    </div>
  );
};

export default App;

