}

export type AppState = 'setup' | 'league';
export type ActiveTab = 'table' | 'matches' | 'market' | 'stadiums';

export const DEFAULT_BOT_NAMES = [
  "Flamengo", "Palmeiras", "São Paulo", "Corinthians", "Atlético-MG", "Grêmio"
];

export const TEAM_COLORS = [
  "#ef4444", "#3b82f6", "#10b981", "#f59e0b", "#8b5cf6", "#ec4899",
];

export const TOTAL_TEAMS = 6;
export const INITIAL_BUDGET = 100000000; // 100 Milhões

export const FIRST_NAMES = ["Ronaldo", "Neymar", "Lucas", "Gabriel", "Bruno", "Felipe", "Diego", "Thiago"];
export const LAST_NAMES = ["Silva", "Santos", "Oliveira", "Souza", "Pereira", "Costa", "Rodrigues", "Alves"];

export const generateRandomPlayer = (id: string): any => {
  const name = `${FIRST_NAMES[Math.floor(Math.random() * FIRST_NAMES.length)]} ${LAST_NAMES[Math.floor(Math.random() * LAST_NAMES.length)]}`;
  const positions: ('GOL' | 'DEF' | 'MEI' | 'ATA')[] = ['GOL', 'DEF', 'MEI', 'ATA'];
  return {
    id,
    name,
    value: Math.floor(Math.random() * 20 + 5) * 1000000, // 5M a 25M
    forSale: false,
    position: positions[Math.floor(Math.random() * positions.length)]
  };
};

import React, { useState } from 'react';
import { Team } from '../types';
import { DEFAULT_BOT_NAMES, TEAM_COLORS, TOTAL_TEAMS, INITIAL_BUDGET, generateRandomPlayer } from '../constants';

interface Props {
  onStart: (teams: Team[]) => void;
}

const SetupForm: React.FC<Props> = ({ onStart }) => {
  const [numHumans, setNumHumans] = useState(1);
  const [humanInputs, setHumanInputs] = useState(
    Array.from({ length: TOTAL_TEAMS }, (_, i) => ({
      playerName: `Jogador ${i + 1}`,
      teamName: `Time ${i + 1}`,
      stadiumName: `Arena ${i + 1}`,
      capacity: 40000
    }))
  );

  const handleStart = () => {
    const finalTeams: Team[] = [];
    const availableBots = [...DEFAULT_BOT_NAMES].sort(() => Math.random() - 0.5);

    for (let i = 0; i < TOTAL_TEAMS; i++) {
      const players = [
        generateRandomPlayer(`p-${i}-1`),
        generateRandomPlayer(`p-${i}-2`),
        generateRandomPlayer(`p-${i}-3`)
      ];

      if (i < numHumans) {
        finalTeams.push({
          id: `team-${i}`,
          name: humanInputs[i].teamName,
          playerName: humanInputs[i].playerName,
          isHuman: true,
          color: TEAM_COLORS[i % TEAM_COLORS.length],
          budget: INITIAL_BUDGET,
          players,
          stadium: {
            name: humanInputs[i].stadiumName,
            primaryColor: TEAM_COLORS[i % TEAM_COLORS.length],
            capacity: humanInputs[i].capacity
          }
        });
      } else {
        const botColor = TEAM_COLORS[(i + 3) % TEAM_COLORS.length];
        finalTeams.push({
          id: `team-${i}`,
          name: availableBots[i - numHumans] || `AI Team ${i}`,
          playerName: 'Computador',
          isHuman: false,
          color: botColor,
          budget: INITIAL_BUDGET,
          players,
          stadium: {
            name: `Estádio Municipal de ${availableBots[i - numHumans]}`,
            primaryColor: botColor,
            capacity: 35000 + Math.floor(Math.random() * 20000)
          }
        });
      }
    }
    onStart(finalTeams);
  };

  return (
    <div className="max-w-4xl mx-auto bg-slate-800 p-8 rounded-2xl shadow-2xl border border-slate-700 animate-in fade-in zoom-in duration-500">
      <h2 className="text-3xl font-black mb-6 text-white text-center">Configurar Campeonato</h2>

      <div className="mb-8 bg-slate-900/50 p-6 rounded-xl border border-slate-700">
        <label className="block text-slate-400 text-sm font-bold mb-4 text-center">Quantos técnicos humanos?</label>
        <div className="grid grid-cols-6 gap-2">
          {[1, 2, 3, 4, 5, 6].map(num => (
            <button
              key={num}
              onClick={() => setNumHumans(num)}
              className={`py-3 rounded-lg font-bold border-2 transition-all ${
                numHumans === num 
                  ? 'bg-blue-600 border-blue-400 text-white' 
                  : 'bg-slate-900 border-slate-700 text-slate-500 hover:bg-slate-700'
              }`}
            >
              {num}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8">
        {Array.from({ length: numHumans }).map((_, i) => (
          <div key={i} className="p-5 bg-slate-900 rounded-xl border border-slate-700 space-y-4">
            <h3 className="text-blue-400 font-bold text-sm uppercase">Treinador {i+1}</h3>
            <div>
              <label className="block text-slate-500 text-[10px] font-bold uppercase mb-1">Nome & Time</label>
              <div className="flex gap-2">
                <input
                  placeholder="Seu Nome"
                  value={humanInputs[i].playerName}
                  onChange={(e) => {
                    const newInputs = [...humanInputs];
                    newInputs[i].playerName = e.target.value;
                    setHumanInputs(newInputs);
                  }}
                  className="w-1/2 bg-slate-800 border border-slate-700 rounded px-3 py-2 text-white text-sm focus:ring-1 focus:ring-blue-500 outline-none"
                />
                <input
                  placeholder="Nome do Clube"
                  value={humanInputs[i].teamName}
                  onChange={(e) => {
                    const newInputs = [...humanInputs];
                    newInputs[i].teamName = e.target.value;
                    setHumanInputs(newInputs);
                  }}
                  className="w-1/2 bg-slate-800 border border-slate-700 rounded px-3 py-2 text-white text-sm focus:ring-1 focus:ring-blue-500 outline-none"
                />
              </div>
            </div>
            <div>
              <label className="block text-slate-500 text-[10px] font-bold uppercase mb-1">Estádio & Capacidade</label>
              <div className="flex gap-2">
                <input
                  placeholder="Nome do Estádio"
                  value={humanInputs[i].stadiumName}
                  onChange={(e) => {
                    const newInputs = [...humanInputs];
                    newInputs[i].stadiumName = e.target.value;
                    setHumanInputs(newInputs);
                  }}
                  className="flex-1 bg-slate-800 border border-slate-700 rounded px-3 py-2 text-white text-sm focus:ring-1 focus:ring-blue-500 outline-none"
                />
                <input
                  type="number"
                  value={humanInputs[i].capacity}
                  onChange={(e) => {
                    const newInputs = [...humanInputs];
                    newInputs[i].capacity = parseInt(e.target.value) || 0;
                    setHumanInputs(newInputs);
                  }}
                  className="w-24 bg-slate-800 border border-slate-700 rounded px-3 py-2 text-white text-sm focus:ring-1 focus:ring-blue-500 outline-none"
                />
              </div>
            </div>
          </div>
        ))}
      </div>

      <button
        onClick={handleStart}
        className="w-full bg-blue-600 hover:bg-blue-500 text-white font-black py-4 rounded-xl transition-all shadow-xl shadow-blue-500/20 uppercase tracking-widest"
      >
        Gerar Campeonato & Estádios
      </button>
    </div>
  );
};

