import React, { useState, useMemo } from 'react';
import { Team, Match, StandingRow, AppState, Player, ActiveTab } from './types';
import SetupForm from './components/SetupForm';
import LeagueTable from './components/LeagueTable';
import MatchList from './components/MatchList';
import TransferMarket from './components/TransferMarket';
import { getLeagueAnalysis } from './services/geminiService';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('setup');
  const [activeTab, setActiveTab] = useState<ActiveTab>('table');
  const [teams, setTeams] = useState<Team[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [analysis, setAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const generateSchedule = (teamList: Team[]) => {
    const rounds: Match[] = [];
    const n = teamList.length;
    const teamIds = teamList.map(t => t.id);

    for (let round = 0; round < n - 1; round++) {
      for (let i = 0; i < n / 2; i++) {
        const home = teamIds[i];
        const away = teamIds[n - 1 - i];
        rounds.push({
          id: `match-${round}-${i}`,
          homeId: home,
          awayId: away,
          homeScore: null,
          awayScore: null,
          round: round + 1
        });
      }
      const last = teamIds.pop()!;
      teamIds.splice(1, 0, last);
    }

    const secondHalf = rounds.map(m => ({
      ...m,
      id: `match-ret-${m.id}`,
      homeId: m.awayId,
      awayId: m.homeId,
      round: m.round + (n - 1)
    }));

    return [...rounds, ...secondHalf];
  };

  const handleStart = (selectedTeams: Team[]) => {
    setTeams(selectedTeams);
    setMatches(generateSchedule(selectedTeams));
    setAppState('league');
  };

  const updateScore = (matchId: string, homeScore: number, awayScore: number) => {
    setMatches(prev => prev.map(m => m.id === matchId ? { ...m, homeScore, awayScore } : m));
  };

  const handleToggleSale = (teamId: string, playerId: string) => {
    setTeams(prev => prev.map(team => {
      if (team.id !== teamId) return team;
      return {
        ...team,
        players: team.players.map(p => p.id === playerId ? { ...p, forSale: !p.forSale } : p)
      };
    }));
  };

  const handleTransfer = (fromId: string, toId: string, player: Player) => {
    const seller = teams.find(t => t.id === fromId);
    const buyer = teams.find(t => t.id === toId);

    if (!seller || !buyer || buyer.budget < player.value) {
      alert("Orçamento insuficiente ou erro na transferência!");
      return;
    }

    setTeams(prev => prev.map(team => {
      if (team.id === fromId) {
        return {
          ...team,
          budget: team.budget + player.value,
          players: team.players.filter(p => p.id !== player.id)
        };
      }
      if (team.id === toId) {
        return {
          ...team,
          budget: team.budget - player.value,
          players: [...team.players, { ...player, forSale: false }]
        };
      }
      return team;
    }));
  };

  const standings = useMemo(() => {
    const stats: Record<string, StandingRow> = {};
    teams.forEach(t => {
      stats[t.id] = {
        teamId: t.id, teamName: t.name, isHuman: t.isHuman,
        played: 0, won: 0, drawn: 0, lost: 0, gf: 0, ga: 0, gd: 0, points: 0, lastFive: []
      };
    });

    const sortedMatches = [...matches].sort((a, b) => a.round - b.round);
    const resultsByTeam: Record<string, ('W' | 'D' | 'L')[]> = {};
    teams.forEach(t => resultsByTeam[t.id] = []);

    sortedMatches.forEach(m => {
      if (m.homeScore !== null && m.awayScore !== null) {
        const home = stats[m.homeId];
        const away = stats[m.awayId];
        home.played++; away.played++;
        home.gf += m.homeScore; home.ga += m.awayScore;
        away.gf += m.awayScore; away.ga += m.homeScore;

        if (m.homeScore > m.awayScore) {
          home.won++; home.points += 3; away.lost++;
          resultsByTeam[m.homeId].push('W'); resultsByTeam[m.awayId].push('L');
        } else if (m.homeScore < m.awayScore) {
          away.won++; away.points += 3; home.lost++;
          resultsByTeam[m.homeId].push('L'); resultsByTeam[m.awayId].push('W');
        } else {
          home.drawn++; away.drawn++; home.points += 1; away.points += 1;
          resultsByTeam[m.homeId].push('D'); resultsByTeam[m.awayId].push('D');
        }
        home.gd = home.gf - home.ga;
        away.gd = away.gf - away.ga;
      }
    });

    return Object.values(stats)
      .map(s => ({ ...s, lastFive: resultsByTeam[s.teamId].slice(-5).reverse() }))
      .sort((a, b) => (b.points - a.points) || (b.won - a.won) || (b.gd - a.gd) || (b.gf - a.gf));
  }, [matches, teams]);

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const result = await getLeagueAnalysis(standings, teams);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  return (
    <div className="min-h-screen pb-20 selection:bg-blue-500/30">
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-30 shadow-xl px-4 py-4 mb-8">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg">
              <span className="text-white font-black text-xl">B</span>
            </div>
            <h1 className="text-xl font-black text-white tracking-tighter hidden sm:block">BRASILEIRÃO MANAGER</h1>
          </div>

          {appState === 'league' && (
            <nav className="flex bg-slate-800 p-1 rounded-lg border border-slate-700">
              <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'table' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white'}`}>Tabela</button>
              <button onClick={() => setActiveTab('matches')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'matches' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white'}`}>Jogos</button>
              <button onClick={() => setActiveTab('market')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'market' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white'}`}>Mercado</button>
              <button onClick={() => setActiveTab('stadiums')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'stadiums' ? 'bg-blue-600 text-white' : 'text-slate-400 hover:text-white'}`}>Estádios</button>
            </nav>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4">
        {appState === 'setup' ? (
          <SetupForm onStart={handleStart} />
        ) : (
          <div className="space-y-8">
            {activeTab === 'table' && (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2">
                  <LeagueTable standings={standings} />
                </div>
                <div className="space-y-6">
                  <section className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700 shadow-xl">
                    <h3 className="text-lg font-black text-white mb-4 flex items-center gap-2">
                      <span className="w-1 h-6 bg-purple-500 rounded"></span> Narrador AI
                    </h3>
                    {analysis ? (
                      <p className="text-slate-300 text-sm italic leading-relaxed">{analysis}</p>
                    ) : (
                      <p className="text-slate-500 text-sm">Clique abaixo para analisar a rodada.</p>
                    )}
                    <button onClick={handleAnalyze} disabled={isAnalyzing} className="w-full mt-4 py-2 bg-purple-600 rounded-lg text-white text-xs font-bold hover:bg-purple-500 transition-all">
                      {isAnalyzing ? 'Pensando...' : 'Pedir Comentário'}
                    </button>
                  </section>
                </div>
              </div>
            )}

            {activeTab === 'matches' && (
              <MatchList matches={matches} teams={teams} onUpdateScore={updateScore} />
            )}

            {activeTab === 'market' && (
              <TransferMarket teams={teams} onToggleSale={handleToggleSale} onTransfer={handleTransfer} />
            )}

            {activeTab === 'stadiums' && (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in">
                {teams.map(team => (
                  <div key={team.id} className="bg-slate-800 rounded-2xl border border-slate-700 overflow-hidden shadow-xl">
                    <div className="h-24 relative overflow-hidden" style={{ backgroundColor: team.stadium.primaryColor + '44' }}>
                      <div className="absolute inset-0 flex items-center justify-center">
                         <div className="w-32 h-16 border-2 border-white/20 rounded-t-full mt-10"></div>
                      </div>
                    </div>
                    <div className="p-6 relative">
                       <div className="absolute -top-10 left-6 w-16 h-16 bg-slate-900 rounded-xl border-4 border-slate-800 flex items-center justify-center font-black text-2xl text-white shadow-2xl">
                          {team.name[0]}
                       </div>
                       <h3 className="mt-8 font-black text-xl text-white">{team.stadium.name}</h3>
                       <p className="text-sm text-slate-400 mb-4">{team.name}</p>
                       <div className="flex justify-between items-center text-xs text-slate-500 font-bold uppercase tracking-wider">
                          <span>Capacidade</span>
                          <span className="text-white">{team.stadium.capacity.toLocaleString()}</span>
                       </div>
                       <div className="mt-4 pt-4 border-t border-slate-700/50 flex gap-2">
                          <span className="px-2 py-1 bg-slate-900 rounded text-[10px] text-slate-400">Gramado Natural</span>
                          <span className="px-2 py-1 bg-slate-900 rounded text-[10px] text-slate-400">Refletores LED</span>
                       </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

export interface Stadium {
  name: string;
  primaryColor: string;
  capacity: number;
}

export interface Team {
  id: string;
  name: string;
  playerName: string;
  isHuman: boolean;
  color: string;
  stadium: Stadium;
}

export interface Match {
  id: string;
  homeId: string;
  awayId: string;
  homeScore: number | null;
  awayScore: number | null;
  round: number;
}

export interface StandingRow {
  teamId: string;
  teamName: string;
  isHuman: boolean;
  played: number;
  won: number;
  drawn: number;
  lost: number;
  gf: number;
  ga: number;
  gd: number;
  points: number;
  lastFive: ('W' | 'D' | 'L' | '-')[];
}

export type AppState = 'setup' | 'league';
export type ActiveTab = 'table' | 'matches' | 'stadiums';

export const DEFAULT_BOT_NAMES = [
  "Flamengo", "Palmeiras", "São Paulo", "Corinthians", "Atlético-MG", "Grêmio"
];

export const TEAM_COLORS = [
  "#ef4444", "#3b82f6", "#10b981", "#f59e0b", "#8b5cf6", "#ec4899",
];

export const TOTAL_TEAMS = 6;

import React, { useState } from 'react';
import { Team } from '../types';
import { DEFAULT_BOT_NAMES, TEAM_COLORS, TOTAL_TEAMS } from '../constants';

interface Props {
  onStart: (teams: Team[]) => void;
}

const SetupForm: React.FC<Props> = ({ onStart }) => {
  const [numHumans, setNumHumans] = useState(1);
  const [humanInputs, setHumanInputs] = useState(
    Array.from({ length: TOTAL_TEAMS }, (_, i) => ({
      playerName: `Jogador ${i + 1}`,
      teamName: `Time ${i + 1}`,
      stadiumName: `Arena ${i + 1}`,
      capacity: 40000
    }))
  );

  const handleStart = () => {
    const finalTeams: Team[] = [];
    const availableBots = [...DEFAULT_BOT_NAMES].sort(() => Math.random() - 0.5);

    for (let i = 0; i < TOTAL_TEAMS; i++) {
      if (i < numHumans) {
        finalTeams.push({
          id: `team-${i}`,
          name: humanInputs[i].teamName,
          playerName: humanInputs[i].playerName,
          isHuman: true,
          color: TEAM_COLORS[i % TEAM_COLORS.length],
          stadium: {
            name: humanInputs[i].stadiumName,
            primaryColor: TEAM_COLORS[i % TEAM_COLORS.length],
            capacity: humanInputs[i].capacity
          }
        });
      } else {
        const botColor = TEAM_COLORS[(i + 3) % TEAM_COLORS.length];
        finalTeams.push({
          id: `team-${i}`,
          name: availableBots[i - numHumans] || `AI Team ${i}`,
          playerName: 'Computador',
          isHuman: false,
          color: botColor,
          stadium: {
            name: `Estádio Municipal de ${availableBots[i - numHumans]}`,
            primaryColor: botColor,
            capacity: 35000 + Math.floor(Math.random() * 20000)
          }
        });
      }
    }
    onStart(finalTeams);
  };

  return (
    <div className="max-w-4xl mx-auto bg-slate-800 p-8 rounded-2xl shadow-2xl border border-slate-700 animate-in fade-in zoom-in duration-500">
      <h2 className="text-3xl font-black mb-6 text-white text-center tracking-tighter">CONFIGURAR CAMPEONATO</h2>

      <div className="mb-8 bg-slate-900/50 p-6 rounded-xl border border-slate-700">
        <label className="block text-slate-400 text-sm font-bold mb-4 text-center uppercase tracking-widest">Técnicos Humanos</label>
        <div className="grid grid-cols-6 gap-2">
          {[1, 2, 3, 4, 5, 6].map(num => (
            <button
              key={num}
              onClick={() => setNumHumans(num)}
              className={`py-3 rounded-lg font-bold border-2 transition-all ${
                numHumans === num 
                  ? 'bg-blue-600 border-blue-400 text-white' 
                  : 'bg-slate-900 border-slate-700 text-slate-500 hover:bg-slate-700'
              }`}
            >
              {num}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8">
        {Array.from({ length: numHumans }).map((_, i) => (
          <div key={i} className="p-5 bg-slate-900 rounded-xl border border-slate-700 space-y-4">
            <h3 className="text-blue-400 font-bold text-xs uppercase tracking-widest">Treinador {i+1}</h3>
            <div>
              <label className="block text-slate-500 text-[10px] font-bold uppercase mb-1">Identidade</label>
              <div className="flex gap-2">
                <input
                  placeholder="Seu Nome"
                  value={humanInputs[i].playerName}
                  onChange={(e) => {
                    const newInputs = [...humanInputs];
                    newInputs[i].playerName = e.target.value;
                    setHumanInputs(newInputs);
                  }}
                  className="w-1/2 bg-slate-800 border border-slate-700 rounded px-3 py-2 text-white text-sm focus:ring-1 focus:ring-blue-500 outline-none"
                />
                <input
                  placeholder="Nome do Clube"
                  value={humanInputs[i].teamName}
                  onChange={(e) => {
                    const newInputs = [...humanInputs];
                    newInputs[i].teamName = e.target.value;
                    setHumanInputs(newInputs);
                  }}
                  className="w-1/2 bg-slate-800 border border-slate-700 rounded px-3 py-2 text-white text-sm focus:ring-1 focus:ring-blue-500 outline-none"
                />
              </div>
            </div>
            <div>
              <label className="block text-slate-500 text-[10px] font-bold uppercase mb-1">Sede do Clube</label>
              <div className="flex gap-2">
                <input
                  placeholder="Nome do Estádio"
                  value={humanInputs[i].stadiumName}
                  onChange={(e) => {
                    const newInputs = [...humanInputs];
                    newInputs[i].stadiumName = e.target.value;
                    setHumanInputs(newInputs);
                  }}
                  className="flex-1 bg-slate-800 border border-slate-700 rounded px-3 py-2 text-white text-sm focus:ring-1 focus:ring-blue-500 outline-none"
                />
                <input
                  type="number"
                  placeholder="Capacidade"
                  value={humanInputs[i].capacity}
                  onChange={(e) => {
                    const newInputs = [...humanInputs];
                    newInputs[i].capacity = parseInt(e.target.value) || 0;
                    setHumanInputs(newInputs);
                  }}
                  className="w-24 bg-slate-800 border border-slate-700 rounded px-3 py-2 text-white text-sm focus:ring-1 focus:ring-blue-500 outline-none"
                />
              </div>
            </div>
          </div>
        ))}
      </div>

      <button
        onClick={handleStart}
        className="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-black py-4 rounded-xl transition-all shadow-xl shadow-emerald-500/20 uppercase tracking-widest active:scale-95"
      >
        Iniciar Temporada
      </button>
    </div>
  );
};

