export const DEFAULT_BOT_NAMES = [
  "Flamengo", "Palmeiras", "São Paulo", "Corinthians", "Atlético-MG", "Grêmio"
];

export const TEAM_COLORS = [
  "#ef4444", "#3b82f6", "#10b981", "#f59e0b", "#8b5cf6", "#ec4899",
];

export const TOTAL_TEAMS = 6;
export const INITIAL_BUDGET = 150000000; // 150 Milhões

const FIRST_NAMES = ["Alisson", "Ederson", "Marquinhos", "Casemiro", "Paquetá", "Vinícius", "Rodrygo", "Endrick", "Ganso", "Arrascaeta", "Hulk", "Gabigol", "Everton", "Pedro", "Lucas", "Raphael"];
const LAST_NAMES = ["Jr", "Silva", "Santos", "Souza", "Oliveira", "Pereira", "Costa", "Rodrigues", "Alves", "Teixeira", "Veiga", "Ribeiro", "Guedes"];

export const generateRandomPlayer = (pos?: 'GOL' | 'DEF' | 'MEI' | 'ATA'): any => {
  const positions: ('GOL' | 'DEF' | 'MEI' | 'ATA')[] = ['GOL', 'DEF', 'MEI', 'ATA'];
  const p = pos || positions[Math.floor(Math.random() * positions.length)];
  const rating = 70 + Math.floor(Math.random() * 25);
  // Valor baseado no rating: de 5M a 80M
  const value = (rating - 65) * 3000000 + Math.floor(Math.random() * 5000000);

  return {
    id: Math.random().toString(36).substr(2, 9),
    name: `${FIRST_NAMES[Math.floor(Math.random() * FIRST_NAMES.length)]} ${LAST_NAMES[Math.floor(Math.random() * LAST_NAMES.length)]}`,
    position: p,
    rating,
    value,
    forSale: true
  };
};

import React, { useState, useMemo } from 'react';
