import React, { useState, useMemo } from 'react';
import { Team, Match, StandingRow, AppState, ActiveTab, Player } from './types';
import SetupForm from './components/SetupForm';
import LeagueTable from './components/LeagueTable';
import MatchList from './components/MatchList';
import TransferMarket from './components/TransferMarket';
import { getLeagueAnalysis } from './services/geminiService';
import { INITIAL_BUDGET, generateRandomPlayer } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('setup');
  const [activeTab, setActiveTab] = useState<ActiveTab>('table');
  const [teams, setTeams] = useState<Team[]>([]);
  const [matches, setMatches] = useState<Match[]>([]);
  const [analysis, setAnalysis] = useState<string>('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const generateSchedule = (teamList: Team[]) => {
    const rounds: Match[] = [];
    const n = teamList.length;
    const teamIds = teamList.map(t => t.id);

    for (let round = 0; round < n - 1; round++) {
      for (let i = 0; i < n / 2; i++) {
        const home = teamIds[i];
        const away = teamIds[n - 1 - i];
        rounds.push({
          id: `match-${round}-${i}`,
          homeId: home,
          awayId: away,
          homeScore: null,
          awayScore: null,
          round: round + 1
        });
      }
      const last = teamIds.pop()!;
      teamIds.splice(1, 0, last);
    }

    const secondHalf = rounds.map(m => ({
      ...m,
      id: `match-ret-${m.id}`,
      homeId: m.awayId,
      awayId: m.homeId,
      round: m.round + (n - 1)
    }));

    return [...rounds, ...secondHalf];
  };

  const handleStart = (selectedTeams: Team[]) => {
    // Inicializar times com alguns jogadores e orçamento
    const teamsWithExtras = selectedTeams.map(team => ({
      ...team,
      budget: INITIAL_BUDGET,
      players: [
        generateRandomPlayer('GOL'),
        generateRandomPlayer('DEF'),
        generateRandomPlayer('DEF'),
        generateRandomPlayer('MEI'),
        generateRandomPlayer('ATA'),
      ]
    }));
    setTeams(teamsWithExtras);
    setMatches(generateSchedule(teamsWithExtras));
    setAppState('league');
  };

  const updateScore = (matchId: string, homeScore: number, awayScore: number) => {
    setMatches(prev => prev.map(m => m.id === matchId ? { ...m, homeScore, awayScore } : m));
  };

  const handleBuyPlayer = (player: Player) => {
    setTeams(prev => prev.map(team => {
      // Por simplicidade, assumimos o primeiro técnico humano como o comprador
      if (team.isHuman) {
        if (team.budget < player.value || team.players.length >= 11) return team;
        return {
          ...team,
          budget: team.budget - player.value,
          players: [...team.players, player]
        };
      }
      return team;
    }));
  };

  const handleSellPlayer = (playerId: string) => {
    setTeams(prev => prev.map(team => {
      if (team.isHuman) {
        const player = team.players.find(p => p.id === playerId);
        if (!player) return team;
        // Venda recupera 80% do valor
        return {
          ...team,
          budget: team.budget + (player.value * 0.8),
          players: team.players.filter(p => p.id !== playerId)
        };
      }
      return team;
    }));
  };

  const standings = useMemo(() => {
    const stats: Record<string, StandingRow> = {};
    teams.forEach(t => {
      stats[t.id] = {
        teamId: t.id, teamName: t.name, isHuman: t.isHuman,
        played: 0, won: 0, drawn: 0, lost: 0, gf: 0, ga: 0, gd: 0, points: 0, lastFive: []
      };
    });

    const sortedMatches = [...matches].sort((a, b) => a.round - b.round);
    const resultsByTeam: Record<string, ('W' | 'D' | 'L')[]> = {};
    teams.forEach(t => resultsByTeam[t.id] = []);

    sortedMatches.forEach(m => {
      if (m.homeScore !== null && m.awayScore !== null) {
        const home = stats[m.homeId];
        const away = stats[m.awayId];
        home.played++; away.played++;
        home.gf += m.homeScore; home.ga += m.awayScore;
        away.gf += m.awayScore; away.ga += m.homeScore;

        if (m.homeScore > m.awayScore) {
          home.won++; home.points += 3; away.lost++;
          resultsByTeam[m.homeId].push('W'); resultsByTeam[m.awayId].push('L');
        } else if (m.homeScore < m.awayScore) {
          away.won++; away.points += 3; home.lost++;
          resultsByTeam[m.homeId].push('L'); resultsByTeam[m.awayId].push('W');
        } else {
          home.drawn++; away.drawn++; home.points += 1; away.points += 1;
          resultsByTeam[m.homeId].push('D'); resultsByTeam[m.awayId].push('D');
        }
        home.gd = home.gf - home.ga;
        away.gd = away.gf - away.ga;
      }
    });

    return Object.values(stats)
      .map(s => ({ ...s, lastFive: resultsByTeam[s.teamId].slice(-5).reverse() }))
      .sort((a, b) => (b.points - a.points) || (b.won - a.won) || (b.gd - a.gd) || (b.gf - a.gf));
  }, [matches, teams]);

  const handleAnalyze = async () => {
    setIsAnalyzing(true);
    const result = await getLeagueAnalysis(standings, teams);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const activeHumanTeam = useMemo(() => teams.find(t => t.isHuman) || teams[0], [teams]);

  return (
    <div className="min-h-screen pb-20 selection:bg-blue-500/30">
      <header className="bg-slate-900 border-b border-slate-800 sticky top-0 z-30 shadow-xl px-4 py-4 mb-8">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-emerald-600 rounded-lg flex items-center justify-center shadow-lg">
              <span className="text-white font-black text-xl">M</span>
            </div>
            <h1 className="text-xl font-black text-white tracking-tighter hidden sm:block">MERCADO DA BOLA</h1>
          </div>

          {appState === 'league' && (
            <nav className="flex bg-slate-800 p-1 rounded-lg border border-slate-700">
              <button onClick={() => setActiveTab('table')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'table' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>Tabela</button>
              <button onClick={() => setActiveTab('matches')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'matches' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>Jogos</button>
              <button onClick={() => setActiveTab('market')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'market' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>Mercado</button>
              <button onClick={() => setActiveTab('stadiums')} className={`px-4 py-1.5 rounded-md text-xs font-bold transition-all ${activeTab === 'stadiums' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>Estádios</button>
            </nav>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4">
        {appState === 'setup' ? (
          <SetupForm onStart={handleStart} />
        ) : (
          <div className="space-y-8">
            {activeTab === 'table' && (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                <div className="lg:col-span-2">
                  <LeagueTable standings={standings} />
                </div>
                <div className="space-y-6">
                  <section className="bg-slate-800/80 rounded-2xl p-6 border border-slate-700 shadow-xl">
                    <h3 className="text-lg font-black text-white mb-4 flex items-center gap-2">
                      <span className="w-1 h-6 bg-purple-500 rounded"></span> Narrador AI
                    </h3>
                    {analysis ? (
                      <p className="text-slate-300 text-sm italic leading-relaxed bg-slate-900/50 p-4 rounded-xl border border-slate-700">{analysis}</p>
                    ) : (
                      <p className="text-slate-500 text-sm italic">O narrador está esperando a rodada acabar para comentar!</p>
                    )}
                    <button onClick={handleAnalyze} disabled={isAnalyzing} className="w-full mt-4 py-3 bg-gradient-to-r from-purple-600 to-indigo-600 rounded-xl text-white text-xs font-black uppercase tracking-widest hover:opacity-90 transition-all shadow-lg shadow-purple-500/20 active:scale-95">
                      {isAnalyzing ? 'Analisando...' : 'Pedir Comentário'}
                    </button>
                  </section>

                  <div className="bg-slate-800 rounded-2xl p-6 border border-slate-700 shadow-xl">
                    <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Seu Patrimônio</h3>
                    <div className="text-2xl font-black text-emerald-400">R$ {(activeHumanTeam.budget / 1000000).toFixed(1)}M</div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'matches' && (
              <MatchList matches={matches} teams={teams} onUpdateScore={updateScore} />
            )}

            {activeTab === 'market' && (
              <TransferMarket 
                activeTeam={activeHumanTeam} 
                allTeams={teams} 
                onBuy={handleBuyPlayer} 
                onSell={handleSellPlayer} 
              />
            )}

            {activeTab === 'stadiums' && (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-4">
                {teams.map(team => (
                  <div key={team.id} className="bg-slate-800 rounded-2xl border border-slate-700 overflow-hidden shadow-xl hover:border-blue-500/50 transition-all group">
                    <div className="h-28 relative overflow-hidden bg-slate-900">
                      <div className="absolute inset-0 opacity-20" style={{ background: `linear-gradient(45deg, ${team.stadium.primaryColor}, transparent)` }}></div>
                      <div className="absolute inset-0 flex items-center justify-center">
                         <div className="w-40 h-20 border-2 border-white/10 rounded-t-full mt-12"></div>
                      </div>
                    </div>
                    <div className="p-6 relative">
                       <div className="absolute -top-12 left-6 w-16 h-16 rounded-xl border-4 border-slate-800 flex items-center justify-center font-black text-2xl text-white shadow-2xl transition-transform group-hover:scale-110" style={{ backgroundColor: team.color }}>
                          {team.name[0]}
                       </div>
                       <h3 className="mt-8 font-black text-xl text-white tracking-tighter">{team.stadium.name}</h3>
                       <p className="text-sm text-slate-400 mb-4 font-medium">{team.name}</p>
                       <div className="flex justify-between items-center text-[10px] text-slate-500 font-black uppercase tracking-wider mb-2">
                          <span>Lotação Máxima</span>
                          <span className="text-white">{team.stadium.capacity.toLocaleString()}</span>
                       </div>
                       <div className="w-full bg-slate-900 h-1.5 rounded-full overflow-hidden">
                          <div className="h-full bg-blue-600 rounded-full" style={{ width: '65%' }}></div>
                       </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
};

export default App;
